  convertHatchBoundaryPaths(g) {
    return g.filter((Q) => Q.num_segs_or_paths > 0).map((Q) => {
      const G = {
        boundaryPathTypeFlag: Q.flag
      };
      if (Q.flag & 2)
        return {
          ...G,
          hasBulge: Q.bulges_present,
          isClosed: Q.closed,
          numberOfVertices: Q.num_segs_or_paths,
          vertices: Q.polyline_paths.map((k) => ({
            x: k.point.x,
            y: k.point.y,
            bulge: k.bulge
          }))
        };
      {
        const k = Q.segs.map((N) => {
          if (N.curve_type == mA.Line)
            return {
              type: rA.Line,
              start: N.first_endpoint,
              end: N.second_endpoint
            };
          if (N.curve_type == mA.CircularArc)
            return {
              type: rA.Circular,
              center: N.center,
              radius: N.radius,
              startAngle: N.start_angle,
              endAngle: N.end_angle,
              isCCW: N.is_ccw
            };
          if (N.curve_type == mA.EllipticArc)
            return {
              type: rA.Elliptic,
              center: N.center,
              end: N.endpoint,
              lengthOfMinorAxis: N.minor_major_ratio,
              startAngle: N.start_angle,
              endAngle: N.end_angle,
              isCCW: N.is_ccw
            };
          if (N.curve_type == mA.Spline)
            return {
              type: rA.Spline,
              degree: N.degree,
              isRational: N.is_rational,
              isPeriodic: N.is_periodic,
              numberOfKnots: N.num_knots,
              numberOfControlPoints: N.num_control_points,
              knots: N.knots,
              controlPoints: N.control_points,
              numberOfFitData: N.num_fitpts,
              fitDatum: N.fitpts,
              startTangent: N.start_tangent,
              endTangent: N.end_tangent
            };
        });
        return {
          ...G,
          numberOfEdges: Q.num_segs_or_paths,
          edges: k
        };
      }
    });
  }
